    (F : bvmap 5 word) fc (m : mem),
  ro_cells asegs m V [C8 (wz 0)] ->
  stk asegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> aceil <= lo ->
  (V + 8 <= lo \/ bv_unsigned sp <= V) ->
  bv_unsigned ra mod 2 = 0 -> mem_inv asegs m ->
