(* [comment removed for export] *)
(* [comment removed for export] *)
Definition eb_frame (junk32 : list byte) (V : Z) (s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [CB 32 junk32; C8 (Z_to_bv 64 V); C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Definition eb_segA_post (sp gp tp s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (V X lo : Z) (s5 s4 s3 s2 s1 s0 ra : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk32,
    ms' = MS (mkR (Z_to_bv 64 AEMPLACE_RET1) (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2
                  (Z_to_bv 64 1) (Z_to_bv 64 X) (Z_to_bv 64 8) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 V) (Z_to_bv 64 0) (Z_to_bv 64 (Z.shiftr (V + 8) 3 + 2147450880)) (Z_to_bv 64 2147450880)
                  s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPNEW) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp + -112, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -112)
    /\ rw_cells asegs m' (bv_unsigned sp + -112) [C8 (Z_to_bv 64 (V + 8)); C8 (Z_to_bv 64 AEMPLACE_RET2)]
    /\ rw_cells asegs m' (bv_unsigned sp + -96) (eb_frame junk32 V s5 s4 s3 s2 s1 s0 ra).

Lemma eb_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (V X lo : Z),
  rw_cells asegs m V [C8 (wz 0); C8 (wz 0); C8 (wz 0)] -> V mod 8 = 0 -> accessible m V 24 -> aapp V 24 ->
  stk asegs m lo (bv_unsigned sp) -> lo + 112 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m -> ACONST m ->
  evt asegs (eb_segA_post sp gp tp s6 s7 s8 s9 s10 s11 F fc V X lo s5 s4 s3 s2 s1 s0 ra m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 V) (Z_to_bv 64 X) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
