(* [comment removed for export] *)
(* [comment removed for export] *)
Definition eb_swap_post (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (SP V A x lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, SP); (SP, SP + 32); (V, V + 24); (sh A, sh A + 1)]%Z m m'
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (SP)
    /\ rw_cells asegs m' V [C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 (A + 8)); C8 (Z_to_bv 64 (A + 8))]
    /\ rw_cells asegs m' (SP) [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 V)]
    /\ rw_cells asegs m' A [C8 (Z_to_bv 64 x)]
    /\ SHAD m' A (cc_shadow 8 8)
    /\ ACONST m'.

Lemma eb_swap : forall ra gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (SP V A x lo shi : Z),
  rw_cells asegs m V [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)] -> V mod 8 = 0 -> accessible m V 24 -> aapp V 24 ->
  rw_cells asegs m (SP) [C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 (A + 8)); C8 (Z_to_bv 64 (A + 8)); C8 (Z_to_bv 64 V)] ->
  SP + 40 <= shi ->
  rw_cells asegs m A [C8 (Z_to_bv 64 x)] -> SHAD m A (cc_shadow 8 8) -> rblock_range A 8 -> shvis m A (A + 8) ->
  (V + 24 <= A \/ A + 8 <= V) ->
  stk asegs m lo (SP) -> lo + ASWAP_STACK <= SP -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 -> mem_inv asegs m ->
  ACONST m -> stack0 m lo shi ->
  0 <= SP ->
  evt asegs (eb_swap_post ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc SP V A x lo m)
    (MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 V) (Z_to_bv 64 SP) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_VEC_STATEP_SWAP_OUT) fc None m (seg_rom asegs)).
