(* [comment removed for export] *)
(* [comment removed for export] *)
Definition eb_segB_post (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (SP V A x lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, SP); (V, V + 24); (A, A + 8); (sh A, sh A + 1)]%Z m m'
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo SP
    /\ rw_cells asegs m' V [C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 (A + 8)); C8 (Z_to_bv 64 (A + 8))]
    /\ rw_cells asegs m' A [C8 (Z_to_bv 64 x)]
    /\ SHAD m' A (cc_shadow 8 8)
    /\ ACONST m'.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

Lemma eb_segB : forall (pcv rax : word) gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (s5v s4v s3v s2v s1v s0v rav : word)
    (F : bvmap 5 word) fc (m : mem) (SP V X A x lo shi : Z) (junk32 junkB : list byte),
  (pcv = Z_to_bv 64 AEMPLACE_RET1 \/ pcv = ret_pc (Z_to_bv 64 AEMPLACE_RET1)) ->
  rw_cells asegs m (SP + -112) [C8 (Z_to_bv 64 (V + 8)); C8 (Z_to_bv 64 AEMPLACE_RET2)] ->
  rw_cells asegs m (SP + -96) (eb_frame junk32 V s5v s4v s3v s2v s1v s0v rav) ->
  rw_cells asegs m V [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)] -> V mod 8 = 0 -> accessible m V 24 -> aapp V 24 ->
  ro_cells asegs m X [C8 (Z_to_bv 64 x)] -> SP <= X -> X + 8 <= shi -> X mod 8 = 0 -> 0 <= x < 2^64 ->
